/**
 * Quiz helpers for the mood test page (`src/pages/MoodTests.tsx`).
 *
 * The quiz questions are generated by the Supabase edge function. When that
 * call fails the user still has to be able to complete a meaningful
 * assessment, so a complete fallback quiz is generated locally. The helpers
 * in this module also validate the AI response before it reaches the state,
 * so a malformed response can never break the quiz.
 */

export interface QuizQuestion {
  id: string;
  question: string;
  options: string[];
}

/** Number of questions the quiz is expected to contain. */
export const QUIZ_QUESTION_COUNT = 8;

const FREQUENCY_OPTIONS = [
  "Not at all",
  "Several days",
  "More than half the days",
  "Nearly every day",
];

const INTENSITY_OPTIONS = [
  "Very mild",
  "Moderate",
  "Quite strong",
  "Very intense",
];

const STRESS_OPTIONS = [
  "Not stressed at all",
  "A little stressed",
  "Quite stressed",
  "Extremely stressed",
];

const SLEEP_OPTIONS = [
  "Restful",
  "Slightly disrupted",
  "Frequently disturbed",
  "Barely sleeping",
];

const CONNECTION_OPTIONS = [
  "Not connected",
  "A little connected",
  "Fairly connected",
  "Deeply connected",
];

const FUNCTIONING_OPTIONS = [
  "Everything is fine",
  "A few difficulties",
  "Quite a few difficulties",
  "Severely affected",
];

const COPING_OPTIONS = ["Not at all", "A little", "Quite well", "Very well"];

/**
 * Build a complete fallback quiz for the given mood.
 *
 * The quiz always contains {@link QUIZ_QUESTION_COUNT} questions with four
 * options each and covers anxiety, depression, stress and wellbeing.
 */
export function buildFallbackQuizQuestions(mood: string): QuizQuestion[] {
  const moodLabel = (mood || "current").trim() || "current";

  return [
    {
      id: "1",
      question: `How would you rate your current ${moodLabel} feelings right now?`,
      options: [...INTENSITY_OPTIONS],
    },
    {
      id: "2",
      question: "How often have you felt nervous, anxious or on edge?",
      options: [...FREQUENCY_OPTIONS],
    },
    {
      id: "3",
      question: "How often have you felt down, depressed or hopeless?",
      options: [...FREQUENCY_OPTIONS],
    },
    {
      id: "4",
      question: "How stressed have you felt about your responsibilities?",
      options: [...STRESS_OPTIONS],
    },
    {
      id: "5",
      question: `How has your sleep been while feeling ${moodLabel}?`,
      options: [...SLEEP_OPTIONS],
    },
    {
      id: "6",
      question: "How connected do you feel to friends and family?",
      options: [...CONNECTION_OPTIONS],
    },
    {
      id: "7",
      question: "How is your day-to-day functioning at the moment?",
      options: [...FUNCTIONING_OPTIONS],
    },
    {
      id: "8",
      question: "How well are you able to cope with stress at the moment?",
      options: [...COPING_OPTIONS],
    },
  ];
}

/** Type guard for a single quiz question. */
export function isQuizQuestion(value: unknown): value is QuizQuestion {
  if (typeof value !== "object" || value === null) {
    return false;
  }

  const candidate = value as Record<string, unknown>;

  return (
    typeof candidate.id === "string" &&
    candidate.id.trim().length > 0 &&
    typeof candidate.question === "string" &&
    candidate.question.trim().length > 0 &&
    Array.isArray(candidate.options) &&
    candidate.options.length > 0 &&
    candidate.options.every(
      (option) => typeof option === "string" && option.trim().length > 0
    )
  );
}

/**
 * Validate the payload returned by the AI and keep the questions that match
 * the {@link QuizQuestion} interface.
 *
 * Returns an empty array when the payload does not contain a usable quiz so
 * that the caller can fall back to {@link buildFallbackQuizQuestions}.
 */
export function parseQuizQuestions(payload: unknown): QuizQuestion[] {
  if (typeof payload !== "object" || payload === null) {
    return [];
  }

  const questions = (payload as { questions?: unknown }).questions;

  if (!Array.isArray(questions)) {
    return [];
  }

  return questions
    .filter(isQuizQuestion)
    .map((question, index) => ({
      id: question.id || String(index + 1),
      question: question.question,
      options: question.options,
    }));
}
